      task.lastAction = "\u062A\u0639\u0630\u0631 \u0627\u0644\u0645\u0631\u0627\u062C\u0639\u0629: \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0623\u0648 \u0627\u0644\u0648\u0643\u064A\u0644 \u063A\u064A\u0631 \u0645\u0648\u062C\u0648\u062F";
