      task.reviewMessages = [
        { role: "system", content: boss.systemPrompt + '\n\u0623\u0646\u062A \u0627\u0644\u0622\u0646 \u0641\u064A \u062F\u0648\u0631 \u0627\u0644\u0645\u0631\u0627\u062C\u0639. \u0642\u064A\u0651\u0645 \u0628\u0635\u062F\u0642 \u0648\u0635\u0631\u0627\u0645\u0629 \u0645\u0647\u0646\u064A\u0629. \u0631\u062F\u0643 \u0643\u0627\u0626\u0646 JSON \u0648\u0627\u062D\u062F \u0641\u0642\u0637:\n{"verdict":"approve|revise|reject","score":0-100,"feedback":"\u062A\u0642\u064A\u064A\u0645 \u0645\u0643\u062A\u0648\u0628 \u0645\u062D\u062F\u062F","requiredChanges":["\u062A\u063A\u064A\u064A\u0631 \u0645\u0637\u0644\u0648\u0628"]}\n\u0627\u0639\u062A\u0645\u062F \u0641\u0642\u0637 \u0645\u0627 \u064A\u062D\u0642\u0642 \u0645\u0639\u0627\u064A\u064A\u0631 \u0627\u0644\u0642\u0628\u0648\u0644 \u0641\u0639\u0644\u064B\u0627. \u0645\u0627 \u062F\u0648\u0646 \u0630\u0644\u0643 revise \u0625\u0646 \u0643\u0627\u0646 \u0642\u0627\u0628\u0644\u064B\u0627 \u0644\u0644\u0625\u0635\u0644\u0627\u062D \u0648reject \u0625\u0646 \u0643\u0627\u0646 \u0636\u0639\u064A\u0641\u064B\u0627 \u062C\u0648\u0647\u0631\u064A\u064B\u0627.' },
        { role: "user", content: "\u0645\u0634\u0631\u0648\u0639: " + project.title + "\n\u0627\u0644\u0647\u062F\u0641 \u0627\u0644\u0623\u0635\u0644\u064A: " + project.goal + "\n\u0627\u0644\u0645\u0647\u0645\u0629: " + task.title + "\n\u0627\u0644\u062A\u0639\u0644\u064A\u0645\u0627\u062A \u0643\u0627\u0646\u062A: " + task.instructions + "\n\u0645\u0639\u0627\u064A\u064A\u0631 \u0627\u0644\u0642\u0628\u0648\u0644: " + (task.acceptanceCriteria || "\u2014") + "\n\u0646\u0641\u0651\u0630\u0647\u0627: " + agent.name + " \u0628\u0646\u0645\u0648\u0630\u062C " + agent.model + "\n\n\u0627\u0644\u0646\u0627\u062A\u062C \u0627\u0644\u0645\u0633\u0644\u0651\u0645 \u062D\u0631\u0641\u064A\u064B\u0627:\n" + deliverable.slice(0, 9e3) }
      ];
